import { View, Text, TextInput, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

let nextId = 3;
const fakeCreate = (product) => new Promise((res) => setTimeout(() => res({ id: "p" + nextId++, ...product }), 200));

function App() {
  const [name, setName] = useState("");
  const [items, setItems] = useState([
    { id: "p1", name: "Чихэвч" }, { id: "p2", name: "Гар цаг" },
  ]);

  function add() {
    if (!name) return;
    fakeCreate({ name: name }).then((created) => {
      setItems((prev) => [...prev, created]);
      setName("");
    });
  }

  return (
    <View style={styles.s}>
      <TextInput nativeID="name" style={styles.input} placeholder="Барааны нэр" value={name} onChangeText={setName} />
      <Pressable nativeID="add" style={styles.btn} onPress={add}><Text style={styles.btnText}>Нэмэх</Text></Pressable>
      {items.map((it) => <Text key={it.id} testID="row" style={styles.row}>{it.name}</Text>)}
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16, gap: 8 },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 12, fontSize: 16 },
  btn: { backgroundColor: "#2563eb", padding: 12, borderRadius: 10, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
  row: { fontSize: 16, paddingVertical: 10, borderBottomWidth: 1, borderColor: "#e2e8f0" },
});

registerRootComponent(App);
